static boolean meetsThreshold(BigDecimal amount, BigDecimal threshold) {
    return amount.compareTo(threshold) > 0 || amount.equals(threshold);
}

static int largest(List<Integer> values) {
    values.sort(Comparator.naturalOrder());
    return values.get(0);
}

static void remember(HashMap<String, String> values, String key, String value) {
    values.putIfAbsent(key, value);
}

